"""Deepgram ASR engine — configuration models.

Exposes a Pydantic **discriminated union** over two concrete variants that each carry
``extra="forbid"``:

- :class:`DeepgramV1ASRConfig` (``type: "v1"``) — ``/v1/listen``, Nova models.
- :class:`DeepgramV2ASRConfig` (``type: "v2"``) — ``/v2/listen``, Flux models.

The public alias :data:`DeepgramASRConfig` wraps the union with a callable
:class:`~pydantic.Discriminator` so Pydantic resolves the correct variant
automatically; callers normally do not need to set ``version`` explicitly.

Docs:
- Nova: https://developers.deepgram.com/reference/speech-to-text/listen-streaming
- Flux: https://developers.deepgram.com/docs/flux/configuration
"""

from typing import Annotated, Any, Optional, Union

from pydantic import ConfigDict, Discriminator, Tag, TypeAdapter, model_validator
from typing_extensions import Literal

from rasa.core.channels.voice_stream.asr.asr_engine import (
    ASRConfigError,
    ASREngineConfig,
)
from rasa.core.channels.voice_stream.asr.deepgram.constants import (
    DEEPGRAM_API_V1,
    DEEPGRAM_API_V2,
    V2_MODEL_PREFIXES,
)


class DeepgramV1ASRConfig(ASREngineConfig):
    """Configuration for the Deepgram v1 (``/v1/listen``) API — Nova models.

    Attributes:
        version: Discriminator field — always ``"v1"`` for this variant.
            Normally auto-detected from the model name; only set explicitly when
            you need to override the inference (e.g. for a model not yet listed
            in ``V2_MODEL_PREFIXES``).
        endpoint: Deepgram API host (default ``api.deepgram.com``).
        endpointing: Milliseconds of silence before end-of-speech.
        smart_format: Apply punctuation and formatting server-side.
        utterance_end_ms: Fallback flush timer in milliseconds.
    """

    version: Literal["v1"] = DEEPGRAM_API_V1
    endpoint: Optional[str] = None
    endpointing: Optional[int] = None
    smart_format: Optional[bool] = None
    utterance_end_ms: Optional[int] = None

    model_config = ConfigDict(extra="forbid")

    @model_validator(mode="after")
    def _validate_language_map_has_language(self) -> "DeepgramV1ASRConfig":
        """Enforce that every language_map entry specifies a language code.

        Deepgram v1 passes ``language`` as a query parameter on every
        connection; omitting it causes the API to reject the request.

        Raises:
            ASRConfigError: When any language_map entry is missing a language.
        """
        for rasa_lang, entry in (self.language_map or {}).items():
            if not entry.language:
                raise ASRConfigError(
                    f"Deepgram v1 language_map entry for '{rasa_lang}' is missing "
                    f"a 'language' value (e.g. 'en'). Deepgram v1 requires an "
                    f"explicit language code for each entry."
                )
        return self


class DeepgramV2ASRConfig(ASREngineConfig):
    """Configuration for the Deepgram v2 (``/v2/listen``) API — Flux models.

    See https://developers.deepgram.com/docs/flux/configuration.

    Attributes:
        version: Discriminator field — always ``"v2"`` for this variant.
            Normally auto-detected from the model name; only set explicitly when
            you need to override the inference.
        endpoint: Deepgram API host (default ``api.deepgram.com``).
        eot_threshold: Confidence threshold for EndOfTurn (0.5–0.9, default 0.7).
        eot_timeout_ms: Max silence before forcing EndOfTurn (500–10000,
            default 5000).
    """

    version: Literal["v2"] = DEEPGRAM_API_V2
    endpoint: Optional[str] = None
    eot_threshold: Optional[float] = None
    eot_timeout_ms: Optional[int] = None

    model_config = ConfigDict(extra="forbid")


def _is_v2_model_name(model: Optional[str]) -> bool:
    """Return True when ``model`` belongs to the v2 (Flux) model family."""
    return any((model or "").startswith(p) for p in V2_MODEL_PREFIXES)


def _select_deepgram_variant(v: Any) -> str:
    """Choose the v1/v2 discriminator tag for an incoming Deepgram config.

    Precedence:
        1. Explicit ``version`` field on the payload (``"v1"`` or ``"v2"``).
        2. Top-level deprecated ``model`` field (backwards compat).
        3. Any ``model`` value inside ``language_map``.
        4. Fall back to ``"v1"``.

    In practice users only need to set ``model`` inside ``language_map``.
    The ``version`` field is an explicit override for edge cases where
    auto-detection from the model name is insufficient.

    Args:
        v: Either a raw config dict or an already-validated config instance.

    Returns:
        ``"v1"`` or ``"v2"``.
    """
    if not isinstance(v, dict):
        return getattr(v, "version", DEEPGRAM_API_V1)

    explicit = v.get("version")
    if explicit in (DEEPGRAM_API_V1, DEEPGRAM_API_V2):
        return explicit

    if _is_v2_model_name(v.get("model")):
        return DEEPGRAM_API_V2

    for entry in (v.get("language_map") or {}).values():
        if isinstance(entry, dict):
            entry_model = entry.get("model")
        else:
            entry_model = getattr(entry, "model", None)
        if _is_v2_model_name(entry_model):
            return DEEPGRAM_API_V2

    return DEEPGRAM_API_V1


# Public type alias — the Deepgram ASR engine accepts either variant.
DeepgramASRConfig = Annotated[
    Union[
        Annotated[DeepgramV1ASRConfig, Tag("v1")],
        Annotated[DeepgramV2ASRConfig, Tag("v2")],
    ],
    Discriminator(_select_deepgram_variant),
]


# TypeAdapter that runs the discriminator at validation time. Module-level so
# Pydantic compiles its core schema once.
DEEPGRAM_CONFIG_ADAPTER: TypeAdapter[DeepgramASRConfig] = TypeAdapter(DeepgramASRConfig)
